  "preferred_configuration": {
    "prize_parts": [
      {
        "ballot_id": "B028",
        "laureates": [
          "Hidetoshi Katori",
          "Jun Ye"
        ],
        "citation": "For the invention and realization of optical lattice clocks."
      }
    ]
  },
  "alternatives": [
    "B001",
    "B039"
  ],
  "statement": {
    "case_for": "Optical lattice clocks are a clear experimental invention that made precision timekeeping a powerful probe of fundamental physics. Their performance has been repeatedly demonstrated and refined across laboratories, and their influence reaches beyond incremental improvements in clocks. Katori's lattice-clock concept and realization and Ye's major experimental advances form a focused attribution for a mature achievement.",
    "case_against": "The history spans a broader clock community, and the boundary between the original invention and later experimental advances needs careful reconstruction. The citation must recognize the foundational clock work without implying that every later improvement belongs to these two people.",
    "responses": [
      {
        "member_id": "eriksson-olle",
        "point": "He recognizes Katori and Ye as pioneers but questions whether the lasting physical significance of precision metrology justifies a prize.",
        "response": "I agree that the case should rest on more than technical performance. Here, the clock is a new instrument for testing fundamental physics, and that scientific reach is already established even as precision continues to improve. The continuing development is a reason to define the citation carefully, not to treat the invention as immature."
      },
      {
        "member_id": "johansson-goran",
        "point": "He sees the two-name attribution for optical lattice clocks as unusually clear, while noting that the boundary between the invention and later precision advances could affect the framing.",
        "response": "I share his view that the attribution is comparatively focused. I would keep the citation on invention and realization of the clocks, then verify the original milestones and each person's role against the historical record before final attribution."
      },
      {
        "member_id": "johansson-goran",
        "point": "He argues that quantum error correction has mature theoretical foundations and experimental demonstrations, though large-scale fault-tolerant machines remain unrealized.",
        "response": "That is a strong case for B039 as foundational theory, and the ongoing work should not erase the conceptual achievement. I would still rank B028 ahead: its central instrument and its precision performance have been repeatedly realized, while the scope of B039 combines distinct theoretical milestones and its experimental reach remains less settled."
      }
    ],
    "uncertainties": [
      "The original milestones and the division of credit between Katori, Ye, and the wider clock community need historical verification."
    ],
    "conflict_note": "None apparent from the supplied profile."
  }
}
